class Solution {
 long long palindrome(long long half,bool odd){
  long long x=half; if(odd) half/=10;
  while(half){x=x*10+half%10;half/=10;} return x;
 }
 bool valid(long long x,int k){
  vector<int> d; while(x){d.push_back(x%k);x/=k;}
  for(int i=0,j=(int)d.size()-1;i<j;++i,--j) if(d[i]!=d[j]) return false;
  return true;
 }
public:
 long long kMirror(int k,int n){
  long long sum=0;
  for(int digits=1;n>0;++digits){
   long long start=1; for(int i=1;i<(digits+1)/2;++i) start*=10;
   for(long long half=start;half<start*10 && n>0;++half){
    long long x=palindrome(half,digits%2);
    if(valid(x,k)){sum+=x;--n;}
   }
  }
  return sum;
 }
};
